import json
for d in ['PB-01-sharadar-coverage','PB-02-eodhd-crosscheck']:
    r=json.load(open(f'probes/{d}/evidence/results.json')); print(d, r['runner'], r['run_at'], r['script_hash'], sorted(r['checks']))
    for k,v in r['checks'].items():
        if k not in ('C1','C2'): print(' ',k,v)"

